const input = $input.first().json;
const texts = input.texts || [];
return texts.map(text => ({ json: { tenant_id: input.tenant_id, conversation_id: input.conversation_id, text } }));

const original = $("Expandir textos").item.json;
const binary = $input.item.binary || {};
const hasAudio = !!(binary.data && binary.data.data);

return {
  json: { tenant_id: original.tenant_id, conversation_id: original.conversation_id, text: original.text, audio_generated: hasAudio },
  binary: hasAudio ? binary : undefined
};
